static const char *arg(int c,char **v,const char *n){for(int i=2;i+1<c;i++)if(!strcmp(v[i],n))return v[i+1];return NULL;}
static char *slurp(const char *p,size_t *n){FILE*f=fopen(p,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3*d,const char*q){char*e=NULL;int r=sqlite3_exec(d,q,NULL,NULL,&e);if(r!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static int mkdir_ok(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static int weather_schema(sqlite3*d,const char*body,size_t n){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.schema')",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,body,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)&&!strcmp((const char*)sqlite3_column_text(q,0),"bonfyre-resource-weather.v1"))ok=1;sqlite3_finalize(q);return ok;}
static int run_quiet(const char*bin,char *const av[]){pid_t p=fork();int status=0;if(p<0)return 0;if(!p){int fd=open("/dev/null",O_WRONLY);if(fd>=0){dup2(fd,STDOUT_FILENO);close(fd);}execv(bin,av);_exit(127);}return waitpid(p,&status,0)>=0&&WIFEXITED(status)&&WEXITSTATUS(status)==0;}
static int save_previous(const char *body,char path[128]){int fd=mkstemp(path);size_t n=strlen(body);if(fd<0)return 0;if(write(fd,body,n)!=(ssize_t)n||fsync(fd)){close(fd);unlink(path);return 0;}close(fd);return 1;}
static int load_previous(sqlite3*d,char **body,char digest[65]){sqlite3_stmt*q=NULL;int found=0;if(sqlite3_prepare_v2(d,"SELECT body,digest FROM resource_weather_snapshot WHERE singleton=1",-1,&q,NULL)!=SQLITE_OK)return 0;if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)&&sqlite3_column_text(q,1)){*body=strdup((const char*)sqlite3_column_text(q,0));snprintf(digest,65,"%s",(const char*)sqlite3_column_text(q,1));found=*body!=NULL;}sqlite3_finalize(q);return found;}
static int store_current(sqlite3*d,const char*body,const char*digest){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT INTO resource_weather_snapshot(singleton,digest,body,updated_at) VALUES(1,?1,?2,?3) ON CONFLICT(singleton) DO UPDATE SET digest=excluded.digest,body=excluded.body,updated_at=excluded.updated_at",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,digest,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,body,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(q,3,(sqlite3_int64)time(NULL));ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);return ok;}
static int delta_files(const char*dir,char paths[][1400],int cap){DIR*h=opendir(dir);struct dirent*e;int n=0;if(!h)return -1;while((e=readdir(h))){size_t z=strlen(e->d_name);if(z<6||strcmp(e->d_name+z-5,".json"))continue;if(n>=cap||snprintf(paths[n],1400,"%s/%s",dir,e->d_name)>=1400){closedir(h);return -1;}n++;}closedir(h);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(strcmp(paths[i],paths[j])>0){char t[1400];memcpy(t,paths[i],sizeof(t));memcpy(paths[i],paths[j],sizeof(t));memcpy(paths[j],t,sizeof(t));}return n;}
int main(int argc,char **argv){const char*dbp=arg(argc,argv,"--db"),*snapshot=arg(argc,argv,"--snapshot"),*delta_bin=arg(argc,argv,"--delta-bin"),*reheat=arg(argc,argv,"--reheat-bin"),*gate=arg(argc,argv,"--weather-gate"),*gdb=arg(argc,argv,"--gate-db"),*address=arg(argc,argv,"--address-db"),*lease=arg(argc,argv,"--lease-db"),*reheat_db=arg(argc,argv,"--reheat-db"),*acquire=arg(argc,argv,"--acquire-dir"),*cancel=arg(argc,argv,"--cancel-dir"),*out=arg(argc,argv,"--out-dir"),*delta_root=arg(argc,argv,"--delta-dir");sqlite3*d=NULL,*mem=NULL;char*body=NULL,*previous=NULL,digest[65]={0},previous_digest[65]={0},previous_path[]="/tmp/bonfyre-weather-previous-XXXXXX",delta_dir[1400],paths[4096][1400];size_t n=0;int files=0,processed=0,baseline=0,unchanged=0,ok=0;
 enum{WT_ADVANCE};static const BfCommandEntry transition_commands[]={{"advance",WT_ADVANCE,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(transition_commands,sizeof(transition_commands)/sizeof(transition_commands[0]),argv[1]);
 if(argc<2||!command||command->id!=WT_ADVANCE||!dbp||!snapshot||!delta_bin||!reheat||!gate||!gdb||!address||!lease||!reheat_db||!out||!delta_root){fputs("usage: bonfyre-resource-weather-transition advance --db DB --snapshot WEATHER --delta-bin BIN --reheat-bin BIN --weather-gate BIN --gate-db DB --address-db DB --lease-db DB --reheat-db DB --acquire-dir DIR --cancel-dir DIR --out-dir DIR --delta-dir DIR\n",stderr);return 2;}if(!(body=slurp(snapshot,&n))||sqlite3_open(dbp,&d)!=SQLITE_OK||sqlite3_open(":memory:",&mem)!=SQLITE_OK||!weather_schema(mem,body,n)||!sql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS resource_weather_snapshot(singleton INTEGER PRIMARY KEY CHECK(singleton=1),digest TEXT NOT NULL,body TEXT NOT NULL,updated_at INTEGER NOT NULL);"))goto done;bf_sha256_hex((const uint8_t*)body,n,digest);if(!load_previous(d,&previous,previous_digest)){if(!store_current(d,body,digest))goto done;baseline=1;ok=1;goto report;}if(!strcmp(previous_digest,digest)){unchanged=1;ok=1;goto report;}if(!mkdir_ok(delta_root)||snprintf(delta_dir,sizeof(delta_dir),"%s/%s",delta_root,digest)>=(int)sizeof(delta_dir)||!mkdir_ok(delta_dir)||!save_previous(previous,previous_path))goto done;{char*av[]={(char*)delta_bin,"diff","--old",previous_path,"--new",(char*)snapshot,"--out",delta_dir,NULL};if(!run_quiet(delta_bin,av))goto done;}unlink(previous_path);files=delta_files(delta_dir,paths,4096);if(files<0)goto done;for(int i=0;i<files;i++){char*av[]={(char*)reheat,"reheat","--db",(char*)reheat_db,"--weather-gate",(char*)gate,"--gate-db",(char*)gdb,"--address-db",(char*)address,"--lease-db",(char*)lease,"--weather",(char*)snapshot,"--delta",paths[i],"--acquire-dir",(char*)(acquire?acquire:""),"--cancel-dir",(char*)(cancel?cancel:""),"--out-dir",(char*)out,NULL};if(!run_quiet(reheat,av))goto done;processed++;}if(!store_current(d,body,digest))goto done;ok=1;
report:printf("{\"snapshot_digest\":\"%s\",\"previous_snapshot_digest\":\"%s\",\"baseline\":%s,\"unchanged\":%s,\"delta_files\":%d,\"reheat_deltas_processed\":%d,\"truth\":\"resource_weather_frontier_advanced_after_targeted_reheat\",\"cannot_infer\":[\"weather snapshot -> material admission\",\"reheat -> foreign observation\",\"reheat -> authority\",\"snapshot advance -> semantic completion\"]}\n",digest,previous?previous_digest:"",baseline?"true":"false",unchanged?"true":"false",files,processed);
done:unlink(previous_path);if(mem)sqlite3_close(mem);if(d)sqlite3_close(d);free(body);free(previous);return ok?0:1;}
